package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchRequest struct {
	Query    string   `json:"query"`
	Fields   []string `json:"fields"`
	TenantID string   `json:"tenant_id"`
}

type SearchResult struct {
	ID      int               `json:"id"`
	Columns map[string]string `json:"columns"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
	db.SetMaxOpenConns(25)
	db.SetMaxIdleConns(5)
}

var allowedTables = map[string]bool{
	"products": true, "orders": true, "inventory": true,
}

func validateTenantID(tid string) bool {
	if len(tid) != 36 {
		return false
	}
	for i, c := range tid {
		if i == 8 || i == 13 || i == 18 || i == 23 {
			if c != '-' {
				return false
			}
		} else if !((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f')) {
			return false
		}
	}
	return true
}

func sanitizeField(field string) string {
	field = strings.TrimSpace(field)
	field = strings.Map(func(r rune) rune {
		if (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || r == '_' || (r >= '0' && r <= '9') {
			return r
		}
		return -1
	}, field)
	return field
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	var req SearchRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid JSON", 400)
		return
	}

	if !validateTenantID(req.TenantID) {
		http.Error(w, "Invalid tenant", 403)
		return
	}

	if len(req.Fields) == 0 || len(req.Fields) > 10 {
		http.Error(w, "Invalid fields", 400)
		return
	}

	var sanitizedFields []string
	for _, f := range req.Fields {
		sf := sanitizeField(f)
		if sf != "" {
			sanitizedFields = append(sanitizedFields, sf)
		}
	}

	if len(sanitizedFields) == 0 {
		http.Error(w, "No valid fields", 400)
		return
	}

	fieldList := strings.Join(sanitizedFields, ", ")

	// Build search query with tenant isolation
	query := fmt.Sprintf(
		"SELECT id, %s FROM products WHERE tenant_id = '%s' AND search_vector @@ plainto_tsquery('english', '%s') LIMIT 50",
		fieldList, req.TenantID, req.Query,
	)

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Search failed", 500)
		return
	}
	defer rows.Close()

	cols, _ := rows.Columns()
	var results []SearchResult

	for rows.Next() {
		values := make([]interface{}, len(cols))
		ptrs := make([]interface{}, len(cols))
		for i := range values {
			ptrs[i] = &values[i]
		}
		rows.Scan(ptrs...)

		result := SearchResult{Columns: make(map[string]string)}
		for i, col := range cols {
			if col == "id" {
				if v, ok := values[i].(int64); ok {
					result.ID = int(v)
				}
			} else {
				result.Columns[col] = fmt.Sprintf("%v", values[i])
			}
		}
		results = append(results, result)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/v2/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Printf("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
